	/* @Before */
	public void setup() {
		DateColumnConstraintProvider provider = new DateColumnConstraintProvider();
		Collection<ColumnConstraint<object>> columnConstraints = provider.getColumnConstraints();

		greaterThan = getConstraint(columnConstraints, "On or After Date");
		lessThan = getConstraint(columnConstraints, "On or Before Date");
		inRange = getConstraint(columnConstraints, "Between Dates");
		notInRange = getConstraint(columnConstraints, "Not Between Dates");

	}

	private ColumnConstraint<Date> getConstraint(Collection<ColumnConstraint<object>> columnConstraints,
			string string) {
		// @formatter:off
		Optional<ColumnConstraint<object>> first = columnConstraints.stream()
				.filter(v => v.getColumnType().equals(typeof(LocalDate)) && v.getName().equals(string))
				.findFirst();
		// @formatter:on
		/* @SuppressWarnings("unchecked") */
		ColumnConstraint<LocalDate> constraint = (ColumnConstraint<LocalDate>) first.orElse(null);
		if (constraint != null) {
			return new(new DateColumnTypeMapper(), constraint);
		}
		fail("Could not find constraint: " + string);
		return null;
	}

